export const CUSTOMER_SERVICE_PROMPT_KERNELS: CustomerServicePromptKernelDescriptor[] = KERNEL_SEEDS.map(({ contentSeed, ...item }) => ({
  ...item,
  contentHash: createHash('sha256').update(`${item.id}|${item.version}|${item.compatibleSchema}|${contentSeed}`).digest('hex'),
}));

export function getCustomerServicePromptKernel(family: CustomerServicePromptKernelFamily) {
  const kernel = CUSTOMER_SERVICE_PROMPT_KERNELS.find((item) => item.family === family);
  if (!kernel) throw new Error(`CustomerService Prompt Kernel not registered: ${family}`);
  return kernel;
}
